def maxValidPairSum(nums: list[int], limit: int) -> int:
    nums.sort()
    left = 0
    right = len(nums) - 1
    best = -1
    while left < right:
        s = nums[left] + nums[right]
        if s <= limit:
            best = max(best, s)
            left += 1
        else:
            right -= 1
    return best

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxValidPairSum(std::vector<int>& nums, int limit) {
        std::sort(nums.begin(), nums.end());
        int left = 0, right = (int)nums.size() - 1, best = -1;
        while (left < right) {
            int s = nums[left] + nums[right];
            if (s <= limit) {
                best = std::max(best, s);
                left++;
            } else {
                right--;
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public int maxValidPairSum(int[] nums, int limit) {
        Arrays.sort(nums);
        int left = 0, right = nums.length - 1, best = -1;
        while (left < right) {
            int s = nums[left] + nums[right];
            if (s <= limit) {
                best = Math.max(best, s);
                left++;
            } else {
                right--;
            }
        }
        return best;
    }
}

